import "server-only";

import { brotliDecompressSync } from "node:zlib";
import { BRAZIL_STATES, isBrazilUf } from "@/lib/brazilLocations";

export interface MunicipioBrasileiro { id: number; nome: string; }

type MunicipiosPorUf = Record<string, Array<[number, string]>>;

// Base oficial do IBGE, incorporada na aplicação em 23/10/2026. A carga é
// compactada para não deixar a lista de 5.571 municípios no código legível.
// Ela é descompactada apenas no servidor e elimina a consulta externa durante
// cadastro, edição e listagem de localidades.
const MUNICIPIOS_COMPACTADOS = "";

const MUNICIPIOS_POR_UF: MunicipiosPorUf = JSON.parse(
  brotliDecompressSync(Buffer.from(MUNICIPIOS_COMPACTADOS, "base64")).toString("utf8")
) as MunicipiosPorUf;

const normalizar = (valor: string) => valor
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .trim()
  .toLocaleLowerCase("pt-BR");

export function listarEstadosBrasileiros() {
  return BRAZIL_STATES;
}

export function listarMunicipiosBrasileiros(uf: string): MunicipioBrasileiro[] {
  const sigla = uf.trim().toUpperCase();
  if (!isBrazilUf(sigla)) return [];
  return (MUNICIPIOS_POR_UF[sigla] ?? []).map(([id, nome]) => ({ id, nome }));
}

export function municipioPertenceAoEstado(uf: string, cidade: string): boolean {
  const procurada = normalizar(cidade);
  return listarMunicipiosBrasileiros(uf).some((municipio) => normalizar(municipio.nome) === procurada);
}
